function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 200) return 's needs 1 to 200 characters.';
  if (!/^[A-Z]+( [A-Z]+)*$/.test(s)) return 's must be uppercase words separated by single spaces.';
  return null;
}

