function printVertically(s) {
  const words = s.split(' ');
  let height = 0;
  for (const word of words) {
    height = Math.max(height, word.length);
  }
  const result = [];
  for (let row = 0; row < height; row++) {
    let line = '';
    for (const word of words) {
      line += row < word.length ? word[row] : ' ';
    }
    result.push(line.trimEnd());
  }
  return result;
}

