function printVertically(s) {
  // Drop each letter into a grid cell while scanning s, then read the grid row by row.
  const grid = [];
  let column = 0;
  let depth = 0;
  for (const ch of s) {
    if (ch === ' ') {
      column++;
      depth = 0;
      continue;
    }
    if (!grid[depth]) grid[depth] = [];
    grid[depth][column] = ch;
    depth++;
  }
  return grid.map(cells => {
    const chars = [];
    for (let i = 0; i < cells.length; i++) chars.push(cells[i] === undefined ? ' ' : cells[i]);
    while (chars.length && chars[chars.length - 1] === ' ') chars.pop();
    return chars.join('');
  });
}

