function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const limit = size === 'large' ? 200 : 2 + pick(24);
  const longest = size === 'large' ? [3, 12, 40, 200][pick(4)] : 1 + pick(6);
  const words = [];
  let length = -1;
  for (;;) {
    const wordLength = 1 + pick(longest);
    if (words.length && length + 1 + wordLength > limit) break;
    const room = Math.min(wordLength, limit - length - 1);
    let word = '';
    for (let i = 0; i < room; i++) word += letters[pick(letters.length)];
    words.push(word);
    length += 1 + room;
    if (length >= limit - 1) break;
  }
  return [words.join(' ')];
}
